package com.api.steps;

import com.api.context.ScenarioContext;
import com.api.base.EventService;
import com.api.models.request.EventRequest;
import io.cucumber.java.en.When;
import io.restassured.response.Response;

/**
 * Step definitions for the Multiple Events feature (multipleevents.feature).
 *
 * Generated by /featuregenerator from JSON dataset of 10 events.
 *
 * This class adds ONE new step:
 * "I create a full event with title ... capacity {int} price {double} ..."
 * which accepts ALL fields from the EventRequest model, matching the JSON
 * payload.
 *
 * All other steps (filter by category/city, search, fetch by ID, update,
 * delete, status code assertions, "the event is created successfully") are
 * already defined in EventSteps.java and CommonSteps.java — not duplicated
 * here.
 *
 * PicoContainer injects one ScenarioContext per scenario.
 */
public class MultipleEventsSteps {

    private final ScenarioContext context;
    private final EventService eventService;

    public MultipleEventsSteps(ScenarioContext context) {
        this.context = context;
        this.eventService = new EventService();
    }

    // ------------------------------------------------------------------ //
    // Helper — apply JWT token before each authenticated call
    // ------------------------------------------------------------------ //

    private void applyToken() {
        String token = context.getJwtToken();
        if (token != null) {
            eventService.setAuthToken(token);
        }
    }

    // ------------------------------------------------------------------ //
    // POST /events — full payload creation from JSON fields
    //
    // Maps all 10 JSON fields to EventRequest:
    // JSON field → EventRequest field
    // ----------- -----------------
    // title → title
    // description → description
    // category → category
    // eventDate → eventDate (date part: "YYYY-MM-DD")
    // eventTime → eventTime (time part: "HH:mm")
    // venue → location
    // city → city
    // totalSeats → capacity
    // price → price
    // imageUrl → image
    // ------------------------------------------------------------------ //

    @When("I create a full event with title {string} description {string} category {string} date {string} time {string} location {string} city {string} capacity {int} price {double} and image {string}")
    public void iCreateAFullEvent(String title, String description, String category,
            String date, String time, String location, String city,
            int capacity, double price, String imageUrl) {
        applyToken();

        EventRequest request = new EventRequest(
                title,
                description,
                category,
                date,
                time,
                location, // maps to "venue" via @JsonProperty in EventRequest
                city,
                capacity,
                price,
                imageUrl);

        Response response = eventService.createEvent(request);
        context.setLastResponse(response);
    }
}
